    let mut score = post_residual as f64;

    // Dead space avoidance: residuals that are too small to host even the
    // smallest plausible item are "dead" and should be strongly penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Penalize residuals too small for the lookahead item as well.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // Reward tight fits: the closer the item fills the bin, the better.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open
    // with usable space; encourage closing out nearly-full bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64) * 1.5 * (0.5 + 0.5 * progress);

    // Mean residual coupling: if this bin is much emptier than average,
    // it's a good target; if much fuller than average, avoid wasting it.
    let deviation = bin_residual as f64 - mean_residual;
    score += 0.3 * deviation;

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin is a fresh resource; only
    // prefer it when the current bin would leave a large unusable gap.
    if bin_residual == bin_capacity {
        let gap_penalty = if post_residual > 0 && post_residual < 10 { 120.0 } else { 0.0 };
        // Base cost of opening a new bin, offset by keeping residuals large.
        score += 55.0 - 0.5 * (open_bins_count as f64) + gap_penalty;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            // Room for the lookahead item in a fresh bin.
            score -= 15.0;
        }
    }

    score
}

