        score += 200.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless current options are bad
    if bin_residual == bin_capacity {
        score += 120.0;
        // allow new bin late in stream when many bins are open and mean residual is low
        if open_bins_count > 3 && mean_residual < item_size as f64 {
            score -= 100.0;
        }
    }

    // Prefer bins with residual close to item size (tight fit relative to mean)
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.3;

    // Slight preference for bins below mean residual (concentrate fullness)
    if (bin_residual as f64) < mean_residual {
        score -= 10.0;
    }

    // Mild recency effect: later in stream, be more frugal with new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 80.0 * progress;
    }

    score
}

