pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Non-linear waste penalty: penalize small-but-nonzero residuals quadratically
    score += 4.0 * pr_norm * (1.0 - pr_norm) * (1.0 - progress);

    // Reward tight fits (post_residual near 0) increasingly over time
    score -= (1.0 - pr_norm) * (1.0 - pr_norm) * (0.5 + progress);

    // Lookahead coupling: if next item fits the post residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 2.0 * (1.0 - pr_norm) * (0.5 + progress);
    } else if next_item_size > 0 {
        score += 0.5 * pr_norm * progress;
    }

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 3.0 * (1.0 - pr_norm);
    }

    // New-bin candidate: penalize opening a new bin mildly, more so as stream progresses
    if bin_residual == bin_capacity {
        score += 1.5 + 2.0 * progress + 0.1 * open_bins_count as f64;
    } else {
        // Favor fuller bins relative to mean residual
        score += 0.3 * (mean_residual - (bin_residual as f64)) / cap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: overwhelmingly reward.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Harmonic class of post_residual: classify leftover space into
    // "usable" vs "dead" zones via integer division thresholds.
    // Items are 1..=100; treat residuals in [1,10] as near-dead,
    // [11,50] as medium, >50 as roomy.
    let dead_zone = post_residual <= 10;
    let roomy = post_residual > 50;

    if dead_zone {
        // Creating tiny dead space is bad unless it avoids opening a bin.
        score += 60.0;
        if fitting_bins_count == 1 {
            // Last chance: accept anyway.
            score -= 90.0;
        }
    }

    if roomy {
        // Leaving lots of space is fine; slight reward for compacting.
        score -= 10.0;
    }

    // Harmonic coupling with next item: if the next item exactly fits
    // the post_residual, this placement sets up a perfect follow-up.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 250.0;
        } else if next_item_size < post_residual {
            let next_post = post_residual - next_item_size;
            if next_post <= 10 {
                // Would create dead space next round: mild penalty.
                score += 15.0;
            } else {
                score -= 20.0;
            }
        } else {
            // Next item won't fit here; residual becomes a dead class
            // relative to the lookahead.
            score += 25.0;
        }
    }

    // Modulo-arithmetic harmonic classes on capacity fractions.
    // Residuals that are multiples of common item sizes (10,20,25,50)
    // are more likely to be filled exactly later.
    let harmonic_bonus = if post_residual % 50 == 0 {
        40.0
    } else if post_residual % 25 == 0 {
        30.0
    } else if post_residual % 10 == 0 {
        20.0
    } else if post_residual % 5 == 0 {
        10.0
    } else {
        0.0
    };
    score -= harmonic_bonus;

    // New-bin candidate handling: empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Prefer an existing bin with a good (tight) fit; penalize the
        // fresh bin unless existing options are poor.
        // Base cost of opening a new bin:
        score += 120.0;

        // Early in the stream, opening bins is cheap (build a pool).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 80.0 * (1.0 - progress);

        // If many bins are open but few fit, opening a new one is fine.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }

        // If the current item is large relative to capacity, a fresh bin
        // keeps flexibility for the future.
        if item_size * 2 >= bin_capacity {
            score -= 30.0;
        }
    } else if fitting_bins_count == 1 {
        // This is the only existing bin that fits: strong reward to use it
        // instead of opening a new bin.
        score -= 70.0;
    }

    // Mean residual context: if this bin's residual is far below the mean,
    // it's already tight — filling it further is good (keeps loose bins open).
    let residual_gap = mean_residual - bin_residual as f64;
    if residual_gap > 0.0 {
        score -= residual_gap * 0.5;
    } else {
        score += (-residual_gap) * 0.3;
    }

    // Mild penalty per open bin to encourage consolidation late in stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
