    }

    // New-bin candidate handling: only attractive when the item is large
    // (poor fits elsewhere) or few bins are open.
    if bin_residual == bin_capacity {
        score += 35.0; // base cost of opening a new bin
        if item_size >= bin_capacity / 2 {
