    }

    // Prefer bins with residual below mean (consolidating fuller bins).
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Penalize leaving awkward residuals (small but nonzero slivers),
    // which are hard to fill later.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Early in the stream: be more willing to open fresh bins is bad;
    // later: prefer compacting into existing bins.
