pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for tight fits (best-fit core).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Lookahead: if the next item can use this bin's post-residual, reward it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let chain = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - chain / bin_capacity as f64);
        } else {
            // Dead space the next item cannot use: penalize proportionally.
            score += 3.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Penalize spreading across many open bins slightly; encourage filling.
    score += 0.4 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Global pressure: if mean residual is low, avoid wasting large residuals.
    if mean_residual < 25.0 && post_residual > 20 {
        score += 4.0;
    }

    // Time horizon: early in stream, mildly prefer keeping residuals flexible;
    // late in stream, aggressively close out bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 0.05 * post_residual as f64;
    score -= progress * 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: acceptable only when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 30.0;
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / (total_items as f64 - 1.0) } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.8 * progress * norm_pr);
    score -= 2.5 * (1.0 - progress) * norm_pr * norm_pr;

    // Reward tight fits smoothly (quadratic in fill ratio)
    let fill = 1.0 - norm_pr;
    score -= 6.0 * fill * fill * (1.0 + progress);

    // Penalize dead space that no plausible next item fits
    if next_item_size > 0 && post_residual > 0 {
        let gap = post_residual as f64;
        let nxt = next_item_size as f64;
        let waste = (gap - nxt).max(0.0) / cap;
        score += 4.0 * waste * waste;
        // Reward bins that can chain with the lookahead item
        if next_item_size <= post_residual {
            score -= 3.0 * (nxt / cap) * (1.0 - progress);
        }
    }

    // Last-chance bin bonus (smoothly scaled by scarcity)
    if fitting_bins_count == 1 {
        score -= 5.0 * (1.0 + progress);
    }
    // Mild penalty when many bins compete (prefer consolidation)
    score += 0.15 * (fitting_bins_count as f64).powf(1.5);

    // Mean-residual coupling: prefer bins near the mean residual (keeps flexibility)
    let dev = (pr - mean_residual) / cap;
    score += 1.5 * dev * dev;

    // New-bin candidate: penalize opening fresh bins unless nothing fits well
    if bin_residual == bin_capacity {
        score += 12.0 + 20.0 * progress - (item_size as f64 / cap) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: harmonic class of post_residual (small leftovers are gold)
    let pr = post_residual;
    if pr == 0 {
        score -= 1000.0; // perfect fill
    } else if pr <= 5 {
        score -= 400.0;
    } else if pr <= 10 {
        score -= 150.0;
    } else if pr <= 20 {
        score -= 40.0;
    } else if pr <= 30 {
        score -= 8.0;
    }

    // Dead-space penalty for large unusable leftovers (harmonic class 40..50)
    if pr > 40 && pr < 50 {
        score += 60.0;
    }
    // Leftovers in (30,40] pair badly with min item size 10 in original setting
    if pr > 30 && pr <= 40 {
        score += 15.0;
    }

    // Lookahead pairing: does the next item fit into the post-residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // reward proportional to how snugly next item nests
            let slack = (pr - next_item_size) as f64;
            score -= 90.0 - slack * 3.0;
        } else {
            // next item won't fit here; penalize residuals that trap us
            score += 10.0;
        }
        // Harmonic divisibility: post_residual is an exact multiple of next item size
        if next_item_size > 0 && pr % next_item_size == 0 && pr > 0 {
            score -= 25.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // Prefer fuller bins when many bins are open (consolidation pressure)
    let fill_frac = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_frac * (open_bins_count as f64).sqrt() * 20.0;

    // Mean-residual coupling: bins below mean residual (i.e. fuller) get bonus
    score -= (mean_residual - bin_residual as f64) * 0.5;

    // Late in stream: be more conservative, penalize leaving medium residuals
    let progress = step_index as f64 / total_items.max(1) as f64;
    if pr > 25 {
        score += progress * 25.0;
    }

    // New-bin candidate: only attractive when item is huge relative to typical
    // open-bin residuals or nothing fits well; otherwise keep bins closed.
    if bin_residual == bin_capacity {
        let big_item = item_size as f64 > mean_residual + 15.0;
        if big_item {
            score -= 30.0;
        } else {
            score += 45.0 + 0.3 * open_bins_count as f64;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // pairing large items into fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Small post-residuals that cannot host typical items (1..=10) are dead space.
    // Penalize gaps in the "unusable" band harshly; reward exact/near-exact fits.
    if post_residual == 0 {
        // Perfect fit: strongly reward.
        score -= 250.0;
    } else if post_residual <= 5 {
        // Tiny gap: essentially dead unless tiny items arrive; mild reward for tightness.
        score -= 40.0;
    } else if post_residual < 10 {
        // Dead-space band: below the minimum item size (10). Penalize heavily.
        score += 120.0;
    } else if post_residual < 20 {
        // Hard-to-fill band: only very small items fit; moderate penalty.
        score += 45.0;
    } else if post_residual < 35 {
        // Mid band: fillable but wasteful; slight penalty.
        score += 12.0;
    } else {
        // Large residual: flexible space, mild reward to keep bins useful.
        score -= 8.0;
    }

    // Coupling: dead space is worse late in the stream (less time to recover).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual < 10 {
        score += 60.0 * progress;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 150.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item still fits: keep flexibility, mild reward proportional to slack left after it.
        let after_next = post_residual - next_item_size;
        score -= 15.0 + (after_next as f64).min(30.0);
    } else if next_item_size > post_residual {
        // Next item won't fit here anyway: dead space here is less costly.
        score -= 10.0;
    }

    // Last-chance pressure: if this is the only fitting bin, avoid forcing a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual < 10 {
        score -= 50.0;
    }

    // Open-bin pressure: penalize placements that keep many bins open with poor residuals.
    score += (open_bins_count as f64) * 2.0;

    // Deviation from mean residual: prefer bins whose residual is near the mean
    // (balances load across open bins), penalize outliers.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.3;

    // New-bin candidate handling: an empty bin has maximal flexibility.
    // Prefer it when all open bins would leave dead space (< 10), otherwise
    // discourage opening new bins to consolidate load.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // There exist open bins that fit; only open a new one if every fit
            // would create dead space. Approximate: penalize new bin mildly,
            // letting dead-space penalties on open bins dominate.
            score += 30.0 + (open_bins_count as f64) * 3.0;
        } else {
            // No open bin fits: new bin is required; reward it.
            score -= 100.0;
        }
        // Late in stream, slightly discourage opening bins (waste risk).
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits exactly into post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect 2-item packing
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize large leftover space
            score += 0.35 * post_residual as f64;
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than the mean residual
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Last-chance bin bonus: only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize wasting space when few bins are open (encourage consolidation early)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count > 1 {
        score += 0.1 * (1.0 - progress) * post_residual as f64;
    }

    // New-bin candidate: only attractive when nothing fits reasonably
    if bin_residual == bin_capacity {
        score += 45.0 + (open_bins_count as f64) * 2.0;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fill_ratio * fill_ratio;

    // Penalize leaving tiny, hard-to-use dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Lookahead coupling: reward if the leftover residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 4.0;
        }
        // If next item is large, prefer preserving bigger residuals.
        if next_item_size > 50 {
            score += 0.08 * post_residual as f64;
        }
    }

    // Last-chance bin: this is the only bin that fits; strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when current bins fit poorly.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Opening a new bin costs more early (many future items to fill it),
        // so penalize new bins early, less late.
        score += 18.0 * (1.0 - 0.5 * progress);
        // If many bins fit the item, discourage opening a fresh bin.
        score += 3.0 * fitting_bins_count as f64;
        // If the mean residual across open bins is small (bins nearly full),
        // a new bin is reasonable.
        score -= (mean_residual / 10.0).min(15.0);
        // Large items pair well with a fresh bin.
        if item_size > 60 {
            score -= 10.0;
        }
    } else {
        // Slight preference for fuller bins among open candidates (waste-aware).
        score += 0.05 * post_residual as f64;
    }

    // Global state: with many open bins, prefer consolidating into existing ones.
    if open_bins_count > 8 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap; // normalized post residual in [0,1]

    // Base: prefer low post_residual (tight fit)
    let mut score = pr as f64;

    // Smooth non-linear coupling: small post-residuals are strongly rewarded,
    // scaled by stream progress (tighter packing matters as stream advances)
    let tightness = (1.0 - norm_pr) * (1.0 - norm_pr); // in [0,1], high for tight fits
    score -= 30.0 * tightness * (0.4 + 0.6 * progress);

    // Penalize very small dead space only mildly; penalize mid-range waste more
    // via a smooth cubic bump around norm_pr ~ 0.3..0.6 (unusable middles)
    let waste_bump = norm_pr * (1.0 - norm_pr) * (1.0 - norm_pr);
    score += 25.0 * waste_bump * (1.0 - progress);

    // Last-chance bonus: if this is the only fitting bin, reward using it
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress * 0.5);
    }

    // Lookahead: reward if next item could fit into post residual
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if ns <= pr {
            let slack = 1.0 - ((pr - ns) / cap).abs();
            score -= 12.0 * slack * slack;
        } else {
            score += 6.0 * ((ns - pr) / cap);
        }
    }

    // Mild pressure to consolidate: prefer bins with below-mean residual when many bins open
    let mean_term = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * mean_term * (open_bins_count as f64).sqrt() / (1.0 + progress);

    // New-bin candidate: penalize opening a new bin smoothly, more early on
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - progress) + 8.0 * (1.0 - norm_pr);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.05;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    // A residual gap is "dead" if it is smaller than the smallest plausible item.
    let dead_threshold = 9.0f64; // items are >= 1, but typical small items ~10; treat <=9 as waste
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 8.0;
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 25.0;
    }
    // Very tight fits (small but usable gap) get a moderate reward.
    if post_residual > 0 && (post_residual as f64) <= (item_size as f64) * 0.25 {
        score -= 5.0;
    }

    // Open-bin pressure: discourage proliferating bins when few items remain.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 15.0;
        } else if (gap as f64) < dead_threshold {
            score += 4.0; // next item would leave dead space; slight penalty
        } else {
            score -= 6.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot use the leftover; leftover is more likely dead space.
        if post_residual > 0 && (post_residual as f64) < dead_threshold {
            score += 6.0;
        }
    }

    // New-bin candidate handling: an empty bin has large residual; make it
    // moderately attractive only when existing bins would create dead space
    // or when open-bin count is low. Otherwise prefer filling existing bins.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 20.0;
        // Cheaper to open a bin early in the stream.
        score -= 15.0 * (1.0 - progress);
        // If many open bins already, opening another is less costly than fragmenting.
        score -= (open_bins_count as f64).min(10.0) * 1.5;
        // If mean residual across open bins is small, existing bins are tight;
        // a fresh bin is reasonable.
        if mean_residual < item_size as f64 {
            score -= 10.0;
        }
    }

    // Mild preference for bins whose residual is close to the item (good fit).
    let fit_diff = (bin_residual as f64 - item_size as f64).abs();
    score += fit_diff * 0.3;

    // Slight penalty for deviating from mean residual (keeps bin loads balanced).
    score += ((bin_residual as f64 - mean_residual).abs()) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space: residuals too small for any item (1..=100 range)
    if post_residual < 1 {
        score += 1000.0;
    } else if post_residual > 0 && post_residual < 10 {
        score += 50.0; // near-dead space
    }

    // Aggressive 2-step lookahead: reward if the NEXT item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0; // perfect chained fit
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 80.0 - slack * 0.5; // good chained fit, decaying with slack
        } else {
            // next item won't fit here; penalize proportionally to overflow
            let overflow = (next_item_size - post_residual) as f64;
            score += overflow * 0.6;
        }
    }

    // Compare post_residual against mean residual: prefer bins whose residual
    // moves closer to the mean (balanced packing), unless it's a tight fit
    let mean_diff_before = (bin_residual as f64 - mean_residual).abs();
    let mean_diff_after = (post_residual as f64 - mean_residual).abs();
    if mean_diff_after < mean_diff_before {
        score -= 10.0;
    } else {
        score += 5.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: make it attractive only when current open bins would leave
    // large unusable residuals; otherwise discourage opening new bins
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // slight bias toward consolidating early, opening fresh bins late
        score = 100.0 - (bin_capacity as f64 - item_size as f64) * 0.5 + progress * 20.0;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 30.0; // fresh bin also serves next item
        }
    }

    // Prefer placing into bins with larger pre-existing residual (fill emptier bins first)
    score -= (bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: bonus proportional to how completely the item fills the bin.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize dead space: residuals too small to be useful later (min item size 1, but
    // small leftovers rarely usable) — quadratic penalty on small post-residuals.
    if post_residual < 10 {
        score += (10 - post_residual) as f64 * 3.0;
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // reward heavily; if post-residual cannot hold the next item, mild penalty.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 50.0;
        } else if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            score += 8.0;
        }
    }

    // Global state: prefer filling bins when many bins are open (consolidation pressure).
    if open_bins_count > 2 {
        score -= (open_bins_count as f64).ln() * 4.0;
    }

    // Mean residual coupling: bins below mean residual are "emptier" — deprioritize
    // them slightly to keep fuller bins absorbing items first.
    let res = bin_residual as f64;
    if res > mean_residual {
        score += (res - mean_residual) * 0.15;
    } else {
        score -= (mean_residual - res) * 0.15;
    }

    // Time horizon: early in the stream, be more willing to open new bins (exploration);
    // late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 12.0;

    // New-bin candidate: neutral baseline; penalize opening a new bin unless the item
    // is large relative to capacity (poor fits elsewhere) or no good option exists.
    if bin_residual == bin_capacity {
        score += 55.0;
        // Large items are hard to place later; opening a fresh bin for them is fine.
        if item_size > bin_capacity / 2 {
            score -= 35.0;
        }
        // Late in stream, discourage new bins more strongly.
        score += progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr;
    score += 40.0 * norm_pr * norm_pr * (0.5 + progress);
    score -= 25.0 * norm_pr * progress * (1.0 - progress);

    // Reward near-perfect fits (small post_residual) with a smooth bonus
    score -= 30.0 * (-pr / 8.0).exp();

    // Penalize leaving dead space that can't fit typical future items
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += 12.0 * (nxt - pr) / cap * (1.0 + progress);
        } else {
            score -= 8.0 * (1.0 - (pr - nxt).min(60.0) / 60.0) * (1.0 - progress);
        }
    }

    // Last-chance bin bonus: avoid opening new bins when only one fits
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - norm_pr);
    }

    // Mild pressure toward consolidating bins as many are open
    score += (open_bins_count as f64).ln() * 3.0 * norm_pr;

    // Mean-residual alignment: prefer bins close to the mean residual
    score += 5.0 * ((pr - mean_residual) / cap).abs();

    // New-bin candidate handling: make empty bins moderately attractive early,
    // less so late, and only when the fit is poor
    if bin_residual == bin_capacity {
        score = pr + 15.0 - 20.0 * progress - 10.0 * (1.0 - (item_size as f64 / cap));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small dead-space" classes (<=10) are highly desirable.
    let tiny_dead = (post_residual <= 10) as i32 as f64;
    score -= 40.0 * tiny_dead;

    // Modulo arithmetic: post_residual divisible by common size steps (10, 20, 25)
    // leaves room for future items of those sizes.
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 6.0; }
        if post_residual % 25 == 0 { score -= 4.0; }
        if post_residual % 20 == 0 { score -= 2.0; }
        // Odd, unharmonic residuals are dead-space prone.
        if post_residual % 2 == 1 { score += 2.5; }
    }

    // Integer-division thresholds: how many items of the NEXT item's size
    // fit in the post residual (k=2 lookahead chaining).
    if next_item_size > 0 && next_item_size <= post_residual {
        let fits_next = post_residual / next_item_size;
        score -= 8.0 * (fits_next as f64).min(3.0);
        // Exact harmonic fit for next item is excellent.
        if post_residual % next_item_size == 0 { score -= 10.0; }
    } else if next_item_size > post_residual {
        // Post residual too small for the lookahead item: mild penalty unless it's tiny.
        score += (post_residual > 0 && post_residual < 15) as i32 as f64 * 5.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: only prefer opening a fresh bin when current fit is bad
    // (large post residual) and the stream is still early/mid.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Baseline cost of opening a new bin, decaying with progress
        // (later in stream, wasted capacity matters less per-bin).
        let open_cost = 55.0 - 25.0 * progress;
        score += open_cost;
        // Opening a new bin is attractive if the item is large (harmonic
        // class of "big" items pairs well with empty bins).
        if item_size >= 60 { score -= 12.0; }
        if item_size >= 80 { score -= 8.0; }
        // If next item is also large, fresh bin can host it later.
        if next_item_size >= 60 { score -= 6.0; }
    }

    // Penalize bins far below mean residual (fragmented outliers) mildly.
    score += ((mean_residual - bin_residual as f64).abs()) * 0.05;

    // Tight packing reward: fraction of capacity consumed by this placement.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * fill_frac;

    // Capacity-fraction thresholds: residual below quarter capacity is bad.
    if post_residual < bin_capacity / 4 && post_residual > 0 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead space avoidance: residuals that are too small to host even the
    // smallest plausible item are "dead" and should be strongly penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Penalize residuals too small for the lookahead item as well.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // Reward tight fits: the closer the item fills the bin, the better.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open
    // with usable space; encourage closing out nearly-full bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64) * 1.5 * (0.5 + 0.5 * progress);

    // Mean residual coupling: if this bin is much emptier than average,
    // it's a good target; if much fuller than average, avoid wasting it.
    let deviation = bin_residual as f64 - mean_residual;
    score += 0.3 * deviation;

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin is a fresh resource; only
    // prefer it when the current bin would leave a large unusable gap.
    if bin_residual == bin_capacity {
        let gap_penalty = if post_residual > 0 && post_residual < 10 { 120.0 } else { 0.0 };
        // Base cost of opening a new bin, offset by keeping residuals large.
        score += 55.0 - 0.5 * (open_bins_count as f64) + gap_penalty;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            // Room for the lookahead item in a fresh bin.
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward bins whose post_residual
    // can host the next item exactly or nearly.
    if next_item_size > 0 {
        let post = post_residual as f64;
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            let slack = post - nxt;
            // Perfect chain match: subtract a big bonus.
            score -= 40.0;
            // Tighter chain (small slack) is even better.
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Post-residual cannot host next item: penalize proportionally
            // to how far off it is, encouraging bins that keep chains alive.
            let gap = nxt - post;
            score += 10.0 * (gap / bin_capacity as f64);
        }
    }

    // Compare post_residual relative to mean residual of open bins:
    // leaving less than the mean (tighter packing) is favorable.
    let cap = bin_capacity as f64;
    let mean = mean_residual.max(0.0);
    let rel = if mean > 0.0 {
        (post_residual as f64 - mean) / mean
    } else {
        0.0
    };
    score += 15.0 * rel.clamp(-1.0, 1.0);

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin wastes capacity equal to
    // bin_residual of some existing bin. Penalize the fresh-bin option so it
    // only wins when every open bin would create large unusable dead space.
    if bin_residual == bin_capacity {
        // Fresh bin: base cost plus lookahead value of its full capacity.
        score = 55.0 + (bin_capacity - post_residual) as f64;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
        }
        // Early in the stream, opening bins is cheaper.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 25.0 * (1.0 - progress);
        // Many open bins already: discourage more sprawl.
        score += 2.0 * open_bins_count as f64;
    }

    // Slight preference for filling larger fraction of the bin.
    score -= 10.0 * (item_size as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits nonlinearly
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space that cannot hold the next item
    if next_item_size > 0 && post_residual > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) < nxt {
            score += 8.0 * (1.0 - (post_residual as f64) / nxt.max(1.0));
        } else {
            score -= 3.0; // post_residual can host next item
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = mean_residual / cap;
        score = cap * (0.55 + 0.35 * pressure) - 6.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Prefer bins with residual far from mean (diversity of gaps)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Slight preference for low post_residual variance proxy
    score += 0.02 * (post_residual as f64).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress (smooth, in [0,1])
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Fit quality: normalized post residual
    let post_frac = post_residual as f64 / cap;
    let item_frac = item_size as f64 / cap;

    // Non-linear tightness reward: quadratically reward small post_residual
    let tightness = (1.0 - post_frac).powi(3); // high when post residual small
    score -= 8.0 * tightness * (1.0 + progress);

    // Penalize unusable dead space: post_residual too small for typical future items
    let dead = if post_frac < item_frac * 0.5 { (item_frac * 0.5 - post_frac).powi(2) } else { 0.0 };
    score += 20.0 * dead;

    // Lookahead coupling: reward if next item fits into post_residual (smooth sigmoid-ish)
    if next_item_size > 0 {
        let nxt = next_item_size as f64 / cap;
        let fits_next = 1.0 / (1.0 + ((post_frac - nxt) * 20.0).exp());
        score -= 6.0 * fits_next;
        // penalize if post residual barely misses next item (creates trap)
        let near_miss = (-((post_frac - nxt) * 15.0).exp()) * (1.0 - post_frac);
        score += 4.0 * near_miss;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 + 15.0 * (1.0 - post_frac);
    }

    // New-bin candidate handling: make empty bin moderately attractive only when
    // existing bins would leave large waste or stream is early
    if bin_residual == bin_capacity {
        let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
        score = cap * (0.55 + 0.35 * (1.0 - progress)) - 12.0 * scarcity * (1.0 - item_frac);
        // early stream: fresh bins fine; late stream: prefer consolidation
        score += 25.0 * progress * (1.0 - scarcity);
    }

    // Mild preference for bins below mean residual (balance consolidation)
    let resid_dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * resid_dev.max(0.0);

    // Fragmentation penalty for very full bins left with tiny slivers
    score += 5.0 * (post_frac * (1.0 - post_frac)).powi(2) * 0.0
        + 2.0 * (post_frac * (1.0 - post_frac));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: extremely strong reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of the post-residual: classify leftover space by
    // integer division thresholds (dead-space zones vs reusable zones).
    // Residuals in [1..10] are nearly dead space -> penalize mildly.
    // Residuals in [11..30] are "small-item zones" -> neutral.
    // Residuals >= 30 are highly reusable -> reward.
    if post_residual > 0 {
        let cls = post_residual / 10; // 0,1,2,3,... classes
        score += match cls {
            0 => 15.0,        // 1..9 : near-dead space
            1 => 0.0,         // 10..19
            2 => -5.0,        // 20..29
            _ => -10.0,       // >=30 : very reusable
        };
    }

    // Reward if the next item fits exactly into the post-residual (harmonic chaining)
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 300.0; // next item makes a perfect fit here
        } else if gap <= 5 {
            score -= 60.0;  // near-perfect chain
        } else {
            score -= (gap as f64).min(50.0) * 0.5;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot use this bin's leftover: leftover becomes dead
        score += (post_residual as f64) * 0.8;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // this bin's fit is terrible. Make the empty bin's score reflect the
    // "waste" of fresh capacity relative to the item.
    if bin_residual == bin_capacity {
        // fresh bin: baseline penalty proportional to unused capacity
        score = (bin_capacity - item_size) as f64 + 20.0;
        // but if the next item is large and current bins are crowded, opening is fine
        if next_item_size >= 50 && fitting_bins_count <= 2 {
            score -= 40.0;
        }
    }

    // Progress-based pressure: late in the stream, consolidate aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (post_residual as f64) * 0.3;

    // Crowded bin pool: prefer reusing existing bins over opening new ones
    if open_bins_count > 4 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // Mean-residual coupling: if this bin is far above the mean residual it is
    // a "hole" — using it reduces fragmentation.
    if bin_residual as f64 > mean_residual + 20.0 {
        score -= 8.0;
    } else if (bin_residual as f64) < mean_residual - 20.0 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (1..100
    // interface => min item = 1, but practical dead space threshold ~10) are
    // unusable waste. Penalize small gaps quadratically.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 40.0; // heavy penalty for tiny dead gaps
    }
    if post_residual == 0 {
        score -= 60.0; // perfect fit is always best
    }

    // Moderate gaps (10..25) are only usable by small items; mild penalty.
    if post_residual >= 10 && post_residual < 25 {
        score += 8.0;
    }

    // Reward bins whose gap exactly matches the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }
    // Penalize leaving a gap that the next item cannot use at all.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 20.0;
    }

    // Open-bins pressure: discourage spreading across many bins when a new
    // empty bin could absorb the item cleanly.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: an empty bin has large residual; make it
    // attractive only when the current bin would leave severe dead space.
    if bin_residual == bin_capacity {
        score += 12.0 + open_bins_count as f64 * 0.5;
        if post_residual < 10 {
            score -= 50.0; // opening fresh bin beats creating dead space
        }
    }

    // Slight preference for tighter fits overall.
    score -= (bin_residual - item_size) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 200.0;
    }

    // If next item cannot fit in the remaining space, penalize dead space creation.
    if next_item_size > 0 && post_residual < next_item_size {
        // Dead space relative to next item; worse when post_residual is small.
        let waste = next_item_size - post_residual;
        score += waste as f64 * 0.5;
        // Tiny unusable remnants are worst.
        if post_residual < 10 {
            score += 30.0;
        }
    }

    // If next item fits snugly with room to spare, mild reward scaled by fit quality.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 - slack.min(50.0) * 0.2;
    }

    // Prefer bins whose residual is below mean (filling the fullest bins first).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Penalize opening new bins, especially early in the stream.
    if bin_residual == bin_capacity {
        score += 40.0 + 80.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 35.0;
    } else if post_residual <= 15 {
        score -= 15.0;
    }

    // Penalize dead space proportional to fraction of capacity wasted.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 20.0 * waste_frac * waste_frac;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }
    // When many bins fit the item, mildly de-prioritize this one to spread load.
    if fitting_bins_count > 2 {
        score += 3.0 * (fitting_bins_count as f64 - 2.0).min(5.0);
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 40.0;
        } else if gap <= 10 {
            score -= 15.0;
        } else {
            score += 5.0;
        }
    }
    // If next item would NOT fit after this placement, mild penalty (loses flexibility).
    if next_item_size > post_residual && next_item_size > 0 {
        score += 8.0;
    }

    // Time horizon: late in stream, be greedy (minimize residual); early, keep flexibility.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;

    // Global state: if mean residual is high, favor filling this bin more aggressively.
    score -= 0.1 * mean_residual.max(0.0) * (1.0 - waste_frac);

    // Penalize leaving residuals that are known-hard to fill (small odd gaps).
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // New-bin candidate: make it attractive only when current bin fits are poor
    // (high waste) or item is large relative to typical residuals.
    if bin_residual == bin_capacity {
        let poor_fits = waste_frac > 0.5 || post_residual > 40;
        if poor_fits {
            score -= 30.0;
        } else {
            score += 15.0;
        }
    }

    // Slight preference for bins that are already partially filled (consolidation).
    score -= 0.05 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    let mut score = pr as f64;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = x * x * (1.0 - x) * (1.0 - progress);
    score -= 40.0 * poly;

    // Reward tight fits more strongly late in the stream
    score -= (1.0 - x) * (1.0 + progress) * 10.0;

    // Penalize dead space relative to mean residual
    score += 0.3 * (pr as f64 - mean_residual).abs();

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - x);
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr as u32 >= next_item_size {
            score -= 8.0 * (nxt / cap) * (1.0 - x);
        } else {
            score += 5.0 * (1.0 - nxt / cap);
        }
    }

    // Mild penalty for proliferation of open bins early on
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with a mild convexity term
    score += 0.05 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Harmonic class of post_residual: dead-space classes are worse
    // Class 0: post_residual == 0 (perfect fill) -> big reward
    if post_residual == 0 {
        score -= 25.0;
    } else {
        // Class bins by post_residual modulo buckets; small leftovers (<10) are dead space
        let pr = post_residual;
        let class = pr % 10;
        // leftovers 1..9 are nearly unusable dead space; penalize quadratically
        if pr < 10 {
            score += 18.0 - (pr as f64); // smaller leftover = worse
        } else if class == 0 {
            // post_residual divisible by 10 aligns with typical item granularity
            score -= 6.0;
        }
        // harmonic division classes: post_residual that divides capacity nicely
        if pr != 0 && bin_capacity % pr == 0 {
            score -= 4.0;
        }
    }

    // Lookahead: does the next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // great: chain placement possible; reward proportional to snugness
            let snug = (post_residual - next_item_size) as f64;
            score -= 10.0 - 0.1 * snug;
            // harmonic: next item exactly matches post_residual
            if next_item_size == post_residual {
                score -= 12.0;
            }
        } else {
            // next item won't fit here; penalize if we leave large unusable gap
            let gap = post_residual as f64;
            if gap < (next_item_size as f64) * 0.5 {
                score += 8.0; // dead space relative to the known future demand
            }
        }
    } else {
        // last item: any residual is pure waste; reward near-perfect fill strongly
        score -= 15.0 - 0.15 * (post_residual as f64);
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is only good when current bins fit poorly
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score = bin_capacity as f64 * 0.6;
        // more open bins with large mean residual -> prefer reusing them
        score += open_bins_count as f64 * 2.0;
        if mean_residual >= item_size as f64 {
            score += 30.0; // some open bin likely has room; don't open a new one
        }
        if fitting_bins_count == 0 {
            score -= 60.0; // no open bin fits -> must open
        }
        // early stream: opening bins is cheaper (need spread of sizes)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
        // if next item is huge, a fresh bin is valuable
        if next_item_size >= bin_capacity / 2 {
            score -= 8.0;
        }
    } else {
        // using an open bin: reward proportional to how full it already is
        let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= 5.0 * fill;
    }

    // mild preference for consolidating when many bins are open
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item
    // (or the lookahead item) are wasted space -> heavy penalty.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // unusable dead space
        } else if next_item_size > 0 && post_residual < next_item_size {
            score += 25.0; // cannot host the next item either
        } else {
            // Usable leftover: reward proportional to how well it matches next item
            if next_item_size > 0 && post_residual >= next_item_size {
                score -= 8.0 * (1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64));
            }
        }
    } else {
        // Perfect fill is ideal
        score -= 40.0;
    }

    // Reward tight fits (small post_residual relative to residual)
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading items
    // into fresh bins; encourage consolidating into existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open-bin pressure
        score += 15.0 + 3.0 * pressure;
    } else {
        score -= 0.5 * pressure;
    }

    // Prefer bins whose residual deviates from the mean toward being fuller
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Lookahead coupling: if next item fits exactly in post_residual, big bonus
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: huge reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item exactly fills the post residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next item fits: mild reward proportional to how well it fills
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 50.0 * fill;
        } else {
            // next item cannot use the leftover: penalize dead space
            let dead = post_residual as f64;
            if dead < next_item_size as f64 {
                score += 0.5 * (next_item_size as f64 - dead);
            }
        }
    }

    // Penalize small unusable residuals (< minimum plausible item size 10)
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless current options are bad
    if bin_residual == bin_capacity {
        score += 120.0;
        // allow new bin late in stream when many bins are open and mean residual is low
        if open_bins_count > 3 && mean_residual < item_size as f64 {
            score -= 100.0;
        }
    }

    // Prefer bins with residual close to item size (tight fit relative to mean)
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.3;

    // Slight preference for bins below mean residual (concentrate fullness)
    if (bin_residual as f64) < mean_residual {
        score -= 10.0;
    }

    // Mild recency effect: later in stream, be more frugal with new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 80.0 * progress;
    }

    score
}
